const scene=document.getElementById('scene'),pivot=document.getElementById('pivot'),building=document.getElementById('building');let rx=53,rz=-30,scale=1,floor='all',mode='stack',panX=0,panY=0;const pointers=new Map();let gesture=null;
for(let i=1;i<=4;i++){let p=document.createElement('div');p.className='plane';p.dataset.floor=i;p.innerHTML=`<div class="slab"></div><img src="${FLOOR_ASSETS[i].image}" draggable="false" alt="대전역 ${i}층"><span class="tag">${i}F</span>`;building.append(p)}
const labels=[];let labelFrame=0;
async function loadLabels(){for(let f=1;f<=4;f++){const data=FLOOR_ASSETS[f].labels;const plane=building.children[f-1];for(const d of data){const anchor=document.createElement('i');anchor.className='label-anchor';anchor.style.left=(d.x*100)+'%';anchor.style.top=(d.y*100)+'%';plane.append(anchor);const label=document.createElement('span');label.className='map-label'+(d.major?' major':'');label.textContent=d.text;document.getElementById('labels').append(label);labels.push({...d,anchorType:d.anchor,f,anchor,label})}}scheduleLabels()}
function scheduleLabels(){cancelAnimationFrame(labelFrame);labelFrame=requestAnimationFrame(placeLabels)}
function placeLabels(){const occupied=[];const canvas=scene.getBoundingClientRect();for(const d of [...labels].sort((a,b)=>Number(b.major)-Number(a.major))){const show=(floor==='all'||+floor===d.f)&&(floor!=='all'||(d.major&&scale>=1.3));d.label.style.display=show?'block':'none';if(!show)continue;const a=d.anchor.getBoundingClientRect();const w=d.label.offsetWidth,h=d.label.offsetHeight;let x=a.x-(d.anchorType==='start'?0:d.anchorType==='end'?w:w/2),y=a.y-h/2;
 const box={x,y,w,h};if(x<canvas.left||y<canvas.top||x+w>canvas.right||y+h>canvas.bottom||occupied.some(b=>x<b.x+b.w+4&&x+w+4>b.x&&y<b.y+b.h+4&&y+h+4>b.y)){d.label.style.display='none';continue}d.label.style.left=(x-canvas.left)+'px';d.label.style.top=(y-canvas.top)+'px';occupied.push(box)}}
function baseSize(){return Math.min(scene.clientHeight*1.22,scene.clientWidth*1.05)}
function fitFloor(){if(floor==='all'){scale=1;panX=panY=0;return}const selected=labels.filter(d=>d.f===+floor);if(!selected.length)return;let minX=Math.min(...selected.map(d=>d.x))-.06,maxX=Math.max(...selected.map(d=>d.x))+.06,minY=Math.min(...selected.map(d=>d.y))-.06,maxY=Math.max(...selected.map(d=>d.y))+.06;const base=baseSize();scale=Math.min(3.4,scene.clientWidth*.75/(base*(maxX-minX)),scene.clientHeight*.7/(base*(maxY-minY)));panX=(.5-(minX+maxX)/2)*base*scale;panY=(.5-(minY+maxY)/2)*base*scale;if(mode==='stack')panY+=(Number(floor)-2.5)*110*Math.sin(rx*Math.PI/180);}
function setScale(value){const next=clamp(value,.25,8);if(floor!=='all'){panX*=next/scale;panY*=next/scale}scale=next;paint()}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function paint(){scene.classList.toggle('flat',mode==='flat');pivot.style.width=`${baseSize()*scale}px`;pivot.style.transform=`translate(calc(-50% + ${panX}px),calc(-50% + ${panY}px)) rotateX(${mode==='stack'?rx:0}deg) rotateZ(${mode==='stack'?rz:0}deg)`;document.getElementById('zoom').textContent=Math.round(scale*100)+'%';document.querySelectorAll('.plane').forEach(p=>{let f=+p.dataset.floor;p.style.display=mode==='stack'||floor==='all'||+floor===f?'block':'none';p.style.opacity=mode==='stack'&&floor!=='all'&&+floor!==f?'.12':'1';p.style.transform=`translateZ(${mode==='stack'?(f-2.5)*110:0}px)`;p.classList.toggle('focused',mode==='stack'&&+floor===f)});document.querySelectorAll('[data-floor]:is(button)').forEach(b=>{b.classList.toggle('active',b.dataset.floor===floor);b.setAttribute('aria-pressed',String(b.dataset.floor===floor))});document.getElementById('flatMode').setAttribute('aria-pressed',String(mode==='flat'));document.getElementById('stackMode').setAttribute('aria-pressed',String(mode==='stack'));document.getElementById('mapOverline').textContent=mode==='flat'?floor+'F · 평면지도':floor==='all'?'건물 전체 · 입체 컷어웨이':floor+'F · 입체 집중 보기';scheduleLabels()}
function basis(){const p=[...pointers.values()];gesture=p.length>1?{distance:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),scale}:p.length?{x:p[0].x,y:p[0].y,rx,rz,panX,panY}:null}
scene.addEventListener('dragstart',e=>e.preventDefault());scene.addEventListener('selectstart',e=>e.preventDefault());
scene.addEventListener('pointerdown',e=>{if(e.button!==0&&e.pointerType==='mouse')return;e.preventDefault();scene.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});basis()});scene.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});let p=[...pointers.values()];if(p.length>1&&gesture.distance>0){setScale(gesture.scale*Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)/gesture.distance)}else if(p.length===1&&gesture){if(mode==='stack'){rz=gesture.rz+(p[0].x-gesture.x)*.35;rx=clamp(gesture.rx-(p[0].y-gesture.y)*.25,0,78)}else{panX=gesture.panX+p[0].x-gesture.x;panY=gesture.panY+p[0].y-gesture.y}}paint()});function release(e){pointers.delete(e.pointerId);basis()}scene.addEventListener('pointerup',release);scene.addEventListener('pointercancel',release);scene.addEventListener('lostpointercapture',release);scene.addEventListener('wheel',e=>{e.preventDefault();setScale(scale*Math.exp(-e.deltaY*.0015))},{passive:false});document.querySelectorAll('button[data-floor]').forEach(b=>b.onclick=()=>{floor=b.dataset.floor;if(mode==='flat'&&floor==='all')floor='3';fitFloor();paint()});document.getElementById('flatMode').onclick=()=>{mode='flat';if(floor==='all')floor='3';fitFloor();paint()};document.getElementById('stackMode').onclick=()=>{mode='stack';fitFloor();paint()};document.getElementById('in').onclick=()=>{setScale(scale*1.2)};document.getElementById('out').onclick=()=>{setScale(scale/1.2)};document.getElementById('left').onclick=()=>{rz-=20;paint()};document.getElementById('right').onclick=()=>{rz+=20;paint()};document.getElementById('reset').onclick=()=>{rx=53;rz=-30;scale=1;floor='all';mode='stack';panX=0;panY=0;paint()};scene.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-'].includes(e.key)){e.preventDefault();if(e.key==='+'||e.key==='=')setScale(scale*1.2);else if(e.key==='-')setScale(scale/1.2);else if(mode==='stack'){rz+=(e.key==='ArrowLeft'?-12:e.key==='ArrowRight'?12:0);rx=clamp(rx+(e.key==='ArrowUp'?-8:e.key==='ArrowDown'?8:0),0,78)}else{panX+=(e.key==='ArrowLeft'?-30:e.key==='ArrowRight'?30:0);panY+=(e.key==='ArrowUp'?-30:e.key==='ArrowDown'?30:0)}paint()}});document.getElementById('largeText').onclick=e=>{const on=document.body.classList.toggle('large-text');e.currentTarget.setAttribute('aria-pressed',String(on))};document.getElementById('contrast').onclick=e=>{const on=document.body.classList.toggle('high-contrast');e.currentTarget.setAttribute('aria-pressed',String(on))};window.addEventListener('resize',()=>{fitFloor();paint()});paint();loadLabels();

// Public hooks for the search overlay on the station map.
window.daejeonPlaces = () => labels.map(d => ({ id: d.id, name: d.text, floor: d.f }));
window.daejeonFocusPlace = id => {
  const target = labels.find(d => d.id === id);
  if (!target) return false;
  floor = String(target.f);
  fitFloor();
  const base = baseSize();
  panX = (.5 - target.x) * base * scale;
  panY = (.5 - target.y) * base * scale;
  labels.forEach(d => d.label.classList.remove('search-hit'));
  target.label.classList.add('search-hit');
  target.major = true;
  paint();
  return true;
};

window.daejeonDrawRoute = (floorNumber, graph, route, from, to) => {
  document.querySelectorAll('.route-overlay').forEach(el => el.remove());
  const plane = building.children[Number(floorNumber) - 1];
  if (!plane || !route?.nodeIds?.length) return;
  const encoded = FLOOR_ASSETS[String(floorNumber)].image.split(',')[1];
  const source = atob(encoded);
  const viewBox = source.match(/viewBox="([^"]+)"/)?.[1];
  if (!viewBox) return;
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('class', 'route-overlay');
  svg.setAttribute('viewBox', viewBox);
  const nodes = new Map(graph.nodes.map(node => [node.id, node]));
  const points = [[from.x, from.y], ...route.nodeIds.map(id => [nodes.get(id)?.x, nodes.get(id)?.y]), [to.x, to.y]]
    .filter(point => point.every(Number.isFinite)).map(point => point.join(',')).join(' ');
  for (const className of ['route-outline', 'route-line']) {
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
    path.setAttribute('class', className); path.setAttribute('points', points); svg.append(path);
  }
  for (const [place, className] of [[from, 'route-start'], [to, 'route-end']]) {
    const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    circle.setAttribute('class', className); circle.setAttribute('cx', place.x); circle.setAttribute('cy', place.y); circle.setAttribute('r', '15'); svg.append(circle);
  }
  plane.append(svg);
  floor = String(floorNumber); fitFloor(); paint();
};
window.daejeonClearRoute = () => document.querySelectorAll('.route-overlay').forEach(el => el.remove());
